import{c as e,ah as t,L as r,O as d,m as h}from"./chunks/framework.YKVbmyBD.js";const m=JSON.parse('{"title":"服务器内特殊玩法","description":"","frontmatter":{},"headers":[],"relativePath":"web-src/acovia-server/special-gameplay.md","filePath":"web-src/acovia-server/special-gameplay.md"}'),i={name:"web-src/acovia-server/special-gameplay.md"};function l(n,a,o,p,s,c){return t(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="服务器内特殊玩法" tabindex="-1">服务器内特殊玩法 <a class="header-anchor" href="#服务器内特殊玩法" aria-label="Permalink to “服务器内特殊玩法”">​</a></h1><p>柏茯灵使用数据包为服务器编写了一些特殊玩法，如下：</p><h2 id="特殊玩法" tabindex="-1">特殊玩法 <a class="header-anchor" href="#特殊玩法" aria-label="Permalink to “特殊玩法”">​</a></h2><h3 id="资源开采处-资源维度" tabindex="-1">资源开采处：资源维度 <a class="header-anchor" href="#资源开采处-资源维度" aria-label="Permalink to “资源开采处：资源维度”">​</a></h3><p>为了服务器的长久发展，柏茯灵不提倡在主世界获取一些不可再生资源，因为这会严重破坏服务器的地形，久而久之服务器的地形会变得支离破碎，所以柏茯灵在内层服务器设立了资源维度来供玩家随意开采。</p><p>进入方式如下：</p><p>在小镇中心找到一个海晶石材质的喷泉，随后底座有一张告示牌，下方是一个命令方块，右键告示牌即可前往资源维度，资源维度同理，可以回到现代。</p><p>如果告示牌不在，可以激活命令方块重新生成。</p><h3 id="商店" tabindex="-1">商店 <a class="header-anchor" href="#商店" aria-label="Permalink to “商店”">​</a></h3><p>小镇内存在数个商店，可以购买物品，某些商店会贩卖特殊商品。</p><h2 id="特殊物品" tabindex="-1">特殊物品 <a class="header-anchor" href="#特殊物品" aria-label="Permalink to “特殊物品”">​</a></h2><h3 id="再生之花" tabindex="-1">再生之花 <a class="header-anchor" href="#再生之花" aria-label="Permalink to “再生之花”">​</a></h3><p>手持再生之花的玩家受到致命伤害时，会立刻被拉回到安全区域，作为死亡不掉落的替代方案。</p><p>合成方法如下：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>花</td><td>末影珍珠</td><td>花</td></tr><tr><td>末影珍珠</td><td>钻石</td><td>末影珍珠</td></tr><tr><td>花</td><td>末影珍珠</td><td>花</td></tr></tbody></table><h3 id="回溯卷轴" tabindex="-1">回溯卷轴 <a class="header-anchor" href="#回溯卷轴" aria-label="Permalink to “回溯卷轴”">​</a></h3><p>右键使用此卷轴，可以回到主城。</p><p>合成方法如下：</p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>纸</td><td>末影珍珠</td><td>纸</td></tr><tr><td>末影珍珠</td><td>纸</td><td>末影珍珠</td></tr><tr><td>纸</td><td>末影珍珠</td><td>纸</td></tr></tbody></table><h3 id="毁" tabindex="-1">毁_ <a class="header-anchor" href="#毁" aria-label="Permalink to “毁_”">​</a></h3><p>可以快速挖掘一切可挖掘的方块，仅供小镇大型拆迁使用，需找服主申领获得。</p><h3 id="建筑棒" tabindex="-1">建筑棒 <a class="header-anchor" href="#建筑棒" aria-label="Permalink to “建筑棒”">​</a></h3><p>可以附魔建筑类特殊附魔方便建造。</p><h3 id="魔导棒" tabindex="-1">魔导棒 <a class="header-anchor" href="#魔导棒" aria-label="Permalink to “魔导棒”">​</a></h3><p>附魔魔道棒类特殊附魔来实现特殊功能。</p><h2 id="特殊附魔" tabindex="-1">特殊附魔 <a class="header-anchor" href="#特殊附魔" aria-label="Permalink to “特殊附魔”">​</a></h2><h3 id="lightning" tabindex="-1">Lightning <a class="header-anchor" href="#lightning" aria-label="Permalink to “Lightning”">​</a></h3><p>弓箭附魔，会在箭的落点 3 格范围内寻找目标并召唤雷击。</p><h3 id="makeway" tabindex="-1">Makeway <a class="header-anchor" href="#makeway" aria-label="Permalink to “Makeway”">​</a></h3><p>建筑棒附魔，对土径方块左键可以快速铺设道路。</p><h3 id="control-ai" tabindex="-1">Control_AI <a class="header-anchor" href="#control-ai" aria-label="Permalink to “Control_AI”">​</a></h3><p>魔导棒附魔，用来开关距离你生物最近的 AI。</p><h3 id="explore" tabindex="-1">Explore <a class="header-anchor" href="#explore" aria-label="Permalink to “Explore”">​</a></h3><p>弓箭附魔，提升弓箭初速度，并在落点产生爆炸。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to “其他”">​</a></h2><h3 id="旧世界-往日维度" tabindex="-1">旧世界：往日维度 <a class="header-anchor" href="#旧世界-往日维度" aria-label="Permalink to “旧世界：往日维度”">​</a></h3><p>往日用来存储过往世界的建筑。玩家的单人生存世界经过柏茯灵的同意后，世界存档内的建筑可被粘贴至往日作为纪念。</p><p>往日内，时间会被锁定在黄昏，设有三个高飞行速度的乐魂，且不会有怪物生成。</p><p><img src="'+h+'" alt="由群友 User_Time 拍摄"></p><blockquote><p>由群友 User_Time 拍摄。</p></blockquote>',40)])])}const _=e(i,[["render",l]]);export{m as __pageData,_ as default};
